"""Small, wholly fictional fixtures; these are not generated by Synthea."""
import json
from pathlib import Path


def generate(directory, extended=False):
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / ("demo-analytics.json" if extended else "demo.json")
    entries = []
    for index in range(1, 4):
        entries.extend([
            {"fullUrl": f"urn:uuid:patient-{index}", "resource": {
                "resourceType": "Patient", "id": f"patient-{index}",
                "birthDate": f"198{index}-01-01", "gender": "female" if index % 2 else "male",
            }},
            {"resource": {
                "resourceType": "Encounter", "id": f"encounter-{index}", "status": "finished",
                "subject": {"reference": f"urn:uuid:patient-{index}"},
                "period": {"start": "2025-01-01T09:00:00Z", "end": "2025-01-01T10:00:00Z"},
            }},
        ])
    if extended:
        for index in range(1, 4):
            code = "44054006" if index < 3 else "38341003"
            display = "Diabetes mellitus type 2" if index < 3 else "Hypertension"
            entries.extend([
                {"resource": {
                    "resourceType": "Condition", "id": f"condition-{index}",
                    "subject": {"reference": f"Patient/patient-{index}"},
                    "code": {"coding": [{"system": "http://snomed.info/sct", "code": code, "display": display}]},
                    "clinicalStatus": {"coding": [{"system": "http://terminology.hl7.org/CodeSystem/condition-clinical", "code": "active"}]},
                    "verificationStatus": {"coding": [{"system": "http://terminology.hl7.org/CodeSystem/condition-ver-status", "code": "confirmed"}]},
                    "onsetDateTime": "2024-06-01",
                }},
                {"resource": {
                    "resourceType": "MedicationRequest", "id": f"medication-{index}",
                    "subject": {"reference": f"urn:uuid:patient-{index}"},
                    "status": "active", "intent": "order", "authoredOn": "2025-01-01",
                    "medicationCodeableConcept": {"coding": [{"system": "http://www.nlm.nih.gov/research/umls/rxnorm", "code": "860975", "display": "Metformin 500 MG Oral Tablet"}]},
                }},
            ])
    entries.append({"resource": {"resourceType": "Patient", "id": "invalid-patient", "birthDate": "invalid"}})
    content = json.dumps({"resourceType": "Bundle", "type": "collection", "entry": entries}, indent=2) + "\n"
    if path.exists() and path.read_text() != content:
        raise ValueError(f"Refusing to overwrite existing file: {path}")
    path.write_text(content)
    return path
